import React, { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useLang } from '../LangContext';

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();
  const { lang, switchLang, t } = useLang();
  const user = JSON.parse(localStorage.getItem('user') || 'null');

  const logout = () => {
    localStorage.removeItem('userToken');
    localStorage.removeItem('user');
    navigate('/');
    window.location.reload();
  };

  const links = [
    { to: '/', label: t.home, end: true },
    { to: '/clients', label: t.clients },
    { to: '/news', label: t.news },
    { to: '/about', label: t.about },
    { to: '/contact', label: t.contact },
  ];

  const LANGS = [
    { code: 'en', label: 'EN' },
    { code: 'am', label: 'አማ' },
    { code: 'or', label: 'OR' },
  ];

  return (
    <nav style={s.nav}>
      <div style={s.inner}>
        <NavLink to="/" style={s.logo}>
          All <span style={{ color: '#f97316' }}>Things</span>
        </NavLink>

        {/* Desktop links */}
        <div style={s.links} className="nav-links">
          {links.map(({ to, label, end }) => (
            <NavLink key={to} to={to} end={end}
              style={({ isActive }) => ({ ...s.link, ...(isActive ? s.active : {}) })}>
              {label}
            </NavLink>
          ))}
          {user ? (
            <>
              <NavLink to="/dashboard" style={({ isActive }) => ({ ...s.link, ...(isActive ? s.active : {}) })}>
                👤 {user.full_name?.split(' ')[0]}
              </NavLink>
              <button onClick={logout} style={{ ...s.link, background: 'none', border: 'none', color: '#ef4444' }}>
                {t.signOut}
              </button>
            </>
          ) : (
            <>
              <NavLink to="/login" style={({ isActive }) => ({ ...s.link, ...(isActive ? s.active : {}) })}>{t.signIn}</NavLink>
              <NavLink to="/register" style={s.cta}>{t.register}</NavLink>
            </>
          )}
          {/* Language switcher */}
          <div className="lang-switcher" style={{ marginLeft: 8 }}>
            {LANGS.map(l => (
              <button key={l.code} className={`lang-btn${lang === l.code ? ' active' : ''}`}
                onClick={() => switchLang(l.code)}>{l.label}</button>
            ))}
          </div>
        </div>

        {/* Mobile: lang + burger */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <div className="lang-switcher">
            {LANGS.map(l => (
              <button key={l.code} className={`lang-btn${lang === l.code ? ' active' : ''}`}
                onClick={() => switchLang(l.code)}>{l.label}</button>
            ))}
          </div>
          <button style={s.burger} className="nav-burger" onClick={() => setOpen(!open)}>
            {open ? '✕' : '☰'}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {open && (
        <div style={s.mobile}>
          {links.map(({ to, label, end }) => (
            <NavLink key={to} to={to} end={end} onClick={() => setOpen(false)}
              style={({ isActive }) => ({ ...s.mobileLink, ...(isActive ? { color: '#f97316' } : {}) })}>
              {label}
            </NavLink>
          ))}
          {user ? (
            <>
              <NavLink to="/dashboard" onClick={() => setOpen(false)} style={s.mobileLink}>👤 {t.myDashboard}</NavLink>
              <button onClick={logout} style={{ ...s.mobileLink, background: 'none', border: 'none', color: '#ef4444', textAlign: 'left', width: '100%', padding: '10px 0' }}>{t.signOut}</button>
            </>
          ) : (
            <>
              <NavLink to="/login" onClick={() => setOpen(false)} style={s.mobileLink}>{t.signIn}</NavLink>
              <NavLink to="/register" onClick={() => setOpen(false)} style={{ ...s.mobileLink, color: '#f97316' }}>{t.register}</NavLink>
            </>
          )}
        </div>
      )}
    </nav>
  );
}

const s = {
  nav: { background: 'rgba(10,10,10,0.97)', backdropFilter: 'blur(10px)', borderBottom: '1px solid #1a1a1a', position: 'sticky', top: 0, zIndex: 100 },
  inner: { maxWidth: 1200, margin: '0 auto', padding: '0 20px', height: 60, display: 'flex', alignItems: 'center', justifyContent: 'space-between' },
  logo: { fontSize: 20, fontWeight: 900, color: '#fff', flexShrink: 0 },
  links: { display: 'flex', alignItems: 'center', gap: 4 },
  link: { padding: '7px 12px', color: '#a3a3a3', fontSize: 14, borderRadius: 8 },
  active: { color: '#f97316' },
  cta: { marginLeft: 6, padding: '8px 18px', background: '#f97316', color: '#000', borderRadius: 8, fontWeight: 700, fontSize: 14 },
  burger: { background: 'none', border: 'none', color: '#fff', fontSize: 20, padding: 4, display: 'none' },
  mobile: { padding: '8px 20px 16px', borderTop: '1px solid #1a1a1a' },
  mobileLink: { display: 'block', padding: '10px 0', color: '#a3a3a3', fontSize: 15, borderBottom: '1px solid #111' },
};
